/// Encapsulates numeric value that can be either absolute or relative.
class FixedOrPercent {
  /// Absolute value of VM instances calculated based on the specific mode.
  ///
  ///
  ///
  ///     - If the value is fixed, then the calculated
  ///      value is equal to the fixed value.
  ///     - If the value is a percent, then the
  ///     calculated
  ///      value is percent/100 * targetSize.
  ///
  /// For example,
  ///      the calculated value of a 80% of a managed instance group
  /// with 150 instances would be (80/100 * 150) = 120 VM instances. If there
  ///      is a remainder, the number is rounded.
  ///
  /// Output only.
  core.int? calculated;

  /// Specifies a fixed number of VM instances.
  ///
  /// This must be a positive integer.
  core.int? fixed;

  /// Specifies a percentage of instances between 0 to 100%, inclusive.
  ///
  /// For
  /// example, specify 80 for 80%.
  core.int? percent;

  FixedOrPercent({this.calculated, this.fixed, this.percent});

  FixedOrPercent.fromJson(core.Map json_)
    : this(
        calculated: json_['calculated'] as core.int?,
        fixed: json_['fixed'] as core.int?,
        percent: json_['percent'] as core.int?,
      );

  core.Map<core.String, core.dynamic> toJson() {
    final calculated = this.calculated;
    final fixed = this.fixed;
    final percent = this.percent;
    return {'calculated': ?calculated, 'fixed': ?fixed, 'percent': ?percent};
  }
}

/// Specifies a flexible time range with flexible start time and duration.
