/// Represents status related to the future reservation.
///
/// Output only.
class FutureReservationStatus {
  /// The current status of the requested amendment.
  ///
  /// Output only.
  /// Possible string values are:
  /// - "AMENDMENT_APPROVED" : The requested amendment to the Future Resevation
  /// has been approved and
  /// applied by GCP.
  /// - "AMENDMENT_DECLINED" : The requested amendment to the Future Reservation
  /// has been declined by
  /// GCP and the original state was restored.
  /// - "AMENDMENT_IN_REVIEW" : The requested amendment to the Future
  /// Reservation is currently being
  /// reviewd by GCP.
  /// - "AMENDMENT_STATUS_UNSPECIFIED"
  core.String? amendmentStatus;

  /// Fully qualified urls of the automatically created reservations at
  /// start_time.
  ///
  /// Output only.
  core.List<core.String>? autoCreatedReservations;

  /// Exapool provisioned capacities for each SKU type.
  ///
  /// Output only.
  StoragePoolExapoolProvisionedCapacityGb? exapoolProvisionedCapacityGb;

  /// Represents the existing matching usage for the future
  /// reservation.
  ///
  /// Output only.
  FutureReservationStatusExistingMatchingUsageInfo? existingMatchingUsageInfo;

  /// This count indicates the fulfilled capacity so far.
  ///
  /// This is set during
  /// "PROVISIONING" state. This count also includes capacity delivered as part
  /// of existing matching reservations.
  ///
  /// Output only.
  core.String? fulfilledCount;

  /// This field represents the future reservation before an
  /// amendment was requested.
  ///
  /// If the amendment is declined, the Future
  /// Reservation will be reverted to the last known good state. The last known
  /// good state is not set when updating a future reservation whose
  /// Procurement Status is DRAFTING.
  ///
  /// Output only.
  FutureReservationStatusLastKnownGoodState? lastKnownGoodState;

  /// Time when Future Reservation would become LOCKED, after which no
  /// modifications to Future Reservation will be allowed.
  ///
  /// Applicable only
  /// after the Future Reservation is in the APPROVED state. The lock_time is
  /// an RFC3339 string. The procurement_status will transition to PROCURING
  /// state at this time.
  ///
  /// Output only.
  core.String? lockTime;

  /// Current state of this Future Reservation
  ///
  /// Output only.
  /// Possible string values are:
  /// - "APPROVED" : Future reservation is approved by GCP.
  /// - "CANCELLED" : Future reservation is cancelled by the customer.
  /// - "COMMITTED" : Future reservation is committed by the customer.
  /// - "DECLINED" : Future reservation is rejected by GCP.
  /// - "DRAFTING" : Related status for PlanningStatus.Draft. Transitions to
  /// PENDING_APPROVAL upon user submitting FR.
  /// - "FAILED" : Future reservation failed. No additional reservations were
  /// provided.
  /// - "FAILED_PARTIALLY_FULFILLED" : Future reservation is partially
  /// fulfilled. Additional reservations were
  /// provided but did not reach total_count reserved instance slots.
  /// - "FULFILLED" : Future reservation is fulfilled completely.
  /// - "PENDING_AMENDMENT_APPROVAL" : An Amendment to the Future Reservation
  /// has been requested. If the
  /// Amendment is declined, the Future Reservation will be restored to the
  /// last known good state.
  /// - "PENDING_APPROVAL" : Future reservation is pending approval by GCP.
  /// - "PROCUREMENT_STATUS_UNSPECIFIED"
  /// - "PROCURING" : Future reservation is being procured by GCP. Beyond this
  /// point, Future
  /// reservation is locked and no further modifications are allowed.
  /// - "PROVISIONING" : Future reservation capacity is being provisioned. This
  /// state will be
  /// entered after start_time, while reservations are being created to
  /// provide total_count reserved instance slots. This state will not
  /// persist past start_time + 24h.
  core.String? procurementStatus;
  FutureReservationStatusSpecificSKUProperties? specificSkuProperties;

  /// Storage pool provisioned capacities for each SKU type.
  ///
  /// Output only.
  FutureReservationStoragePoolProvisionedCapacity?
  storagePoolProvisionedCapacity;

  FutureReservationStatus({
    this.amendmentStatus,
    this.autoCreatedReservations,
    this.exapoolProvisionedCapacityGb,
    this.existingMatchingUsageInfo,
    this.fulfilledCount,
    this.lastKnownGoodState,
    this.lockTime,
    this.procurementStatus,
    this.specificSkuProperties,
    this.storagePoolProvisionedCapacity,
  });

  FutureReservationStatus.fromJson(core.Map json_)
    : this(
        amendmentStatus: json_['amendmentStatus'] as core.String?,
        autoCreatedReservations:
            (json_['autoCreatedReservations'] as core.List?)
                ?.map((value) => value as core.String)
                .toList(),
        exapoolProvisionedCapacityGb:
            json_.containsKey('exapoolProvisionedCapacityGb')
            ? StoragePoolExapoolProvisionedCapacityGb.fromJson(
                json_['exapoolProvisionedCapacityGb']
                    as core.Map<core.String, core.dynamic>,
              )
            : null,
        existingMatchingUsageInfo:
            json_.containsKey('existingMatchingUsageInfo')
            ? FutureReservationStatusExistingMatchingUsageInfo.fromJson(
                json_['existingMatchingUsageInfo']
                    as core.Map<core.String, core.dynamic>,
              )
            : null,
        fulfilledCount: json_['fulfilledCount'] as core.String?,
        lastKnownGoodState: json_.containsKey('lastKnownGoodState')
            ? FutureReservationStatusLastKnownGoodState.fromJson(
                json_['lastKnownGoodState']
                    as core.Map<core.String, core.dynamic>,
              )
            : null,
        lockTime: json_['lockTime'] as core.String?,
        procurementStatus: json_['procurementStatus'] as core.String?,
        specificSkuProperties: json_.containsKey('specificSkuProperties')
            ? FutureReservationStatusSpecificSKUProperties.fromJson(
                json_['specificSkuProperties']
                    as core.Map<core.String, core.dynamic>,
              )
            : null,
        storagePoolProvisionedCapacity:
            json_.containsKey('storagePoolProvisionedCapacity')
            ? FutureReservationStoragePoolProvisionedCapacity.fromJson(
                json_['storagePoolProvisionedCapacity']
                    as core.Map<core.String, core.dynamic>,
              )
            : null,
      );

  core.Map<core.String, core.dynamic> toJson() {
    final amendmentStatus = this.amendmentStatus;
    final autoCreatedReservations = this.autoCreatedReservations;
    final exapoolProvisionedCapacityGb = this.exapoolProvisionedCapacityGb;
    final existingMatchingUsageInfo = this.existingMatchingUsageInfo;
    final fulfilledCount = this.fulfilledCount;
    final lastKnownGoodState = this.lastKnownGoodState;
    final lockTime = this.lockTime;
    final procurementStatus = this.procurementStatus;
    final specificSkuProperties = this.specificSkuProperties;
    final storagePoolProvisionedCapacity = this.storagePoolProvisionedCapacity;
    return {
      'amendmentStatus': ?amendmentStatus,
      'autoCreatedReservations': ?autoCreatedReservations,
      'exapoolProvisionedCapacityGb': ?exapoolProvisionedCapacityGb,
      'existingMatchingUsageInfo': ?existingMatchingUsageInfo,
      'fulfilledCount': ?fulfilledCount,
      'lastKnownGoodState': ?lastKnownGoodState,
      'lockTime': ?lockTime,
      'procurementStatus': ?procurementStatus,
      'specificSkuProperties': ?specificSkuProperties,
      'storagePoolProvisionedCapacity': ?storagePoolProvisionedCapacity,
    };
  }
}

