  ///    - BPS_400M: 400 Mbit/s
  ///    - BPS_500M: 500 Mbit/s
  ///    - BPS_1G: 1 Gbit/s
  ///    - BPS_2G: 2 Gbit/s
  ///    - BPS_5G: 5 Gbit/s
  ///    - BPS_10G: 10 Gbit/s
  ///    - BPS_20G: 20 Gbit/s
  ///    - BPS_50G: 50 Gbit/s
  ///    - BPS_100G: 100 Gbit/s
  ///    - BPS_400G: 400 Gbit/s
  /// Possible string values are:
  /// - "BPS_100G" : 100 Gbit/s
  /// - "BPS_100M" : 100 Mbit/s
  /// - "BPS_10G" : 10 Gbit/s
  /// - "BPS_1G" : 1 Gbit/s
  /// - "BPS_200M" : 200 Mbit/s
  /// - "BPS_20G" : 20 Gbit/s
  /// - "BPS_2G" : 2 Gbit/s
  /// - "BPS_300M" : 300 Mbit/s
  /// - "BPS_400G" : 400 Gbit/s
  /// - "BPS_400M" : 400 Mbit/s
  /// - "BPS_500M" : 500 Mbit/s
  /// - "BPS_50G" : 50 Gbit/s
  /// - "BPS_50M" : 50 Mbit/s
  /// - "BPS_5G" : 5 Gbit/s
