    : this(
        consensusState: json_.containsKey('consensusState')
            ? NetworkPeeringConnectionStatusConsensusState.fromJson(
                json_['consensusState'] as core.Map<core.String, core.dynamic>,
              )
            : null,
        trafficConfiguration: json_.containsKey('trafficConfiguration')
            ? NetworkPeeringConnectionStatusTrafficConfiguration.fromJson(
                json_['trafficConfiguration']
                    as core.Map<core.String, core.dynamic>,
              )
            : null,
        updateStrategy: json_['updateStrategy'] as core.String?,
      );

  core.Map<core.String, core.dynamic> toJson() {
    final consensusState = this.consensusState;
    final trafficConfiguration = this.trafficConfiguration;
    final updateStrategy = this.updateStrategy;
    return {
      'consensusState': ?consensusState,
      'trafficConfiguration': ?trafficConfiguration,
      'updateStrategy': ?updateStrategy,
    };
  }
}

/// The status of update/delete for a consensus peering connection.
///
/// Only set
/// when connection_status.update_strategy isCONSENSUS or a network peering is
/// proposing to update the
/// strategy to CONSENSUS.
class NetworkPeeringConnectionStatusConsensusState {
  /// The status of the delete request.
  /// Possible string values are:
  /// - "DELETE_ACKNOWLEDGED" : Both network admins have agreed this consensus
  /// peering connection can
  /// be deleted.
  /// - "DELETE_STATUS_UNSPECIFIED"
  /// - "LOCAL_CANCEL_REQUESTED" : The local network admin requested to cancel
  /// their delete request
  /// after DELETE_ACKNOWLEDGED.
  /// - "LOCAL_DELETE_REQUESTED" : Network admin has requested deletion of this
  /// peering connection.
  /// - "PEER_CANCEL_REQUESTED" : The peer network admin requested to cancel
  /// their delete request after
  /// DELETE_ACKNOWLEDGED.
  /// - "PEER_DELETE_REQUESTED" : The peer network admin has requested deletion
  /// of this peering
  /// connection.
  core.String? deleteStatus;

  /// The status of the update request.
  /// Possible string values are:
  /// - "IN_SYNC" : No pending configuration update proposals to the peering
  /// connection.
  /// - "PENDING_LOCAL_ACKNOWLEDMENT" : The peer network admin has made an
  /// updatePeering call. The change is
  /// awaiting acknowledgment from this peering's network admin.
  /// - "PENDING_PEER_ACKNOWLEDGEMENT" : The local network admin has made an
  /// updatePeering call. The change
  /// is awaiting acknowledgment from the peer network admin.
  /// - "UPDATE_STATUS_UNSPECIFIED"
  core.String? updateStatus;

  NetworkPeeringConnectionStatusConsensusState({
    this.deleteStatus,
    this.updateStatus,
  });

  NetworkPeeringConnectionStatusConsensusState.fromJson(core.Map json_)
    : this(
        deleteStatus: json_['deleteStatus'] as core.String?,
        updateStatus: json_['updateStatus'] as core.String?,
      );

  core.Map<core.String, core.dynamic> toJson() {
    final deleteStatus = this.deleteStatus;
    final updateStatus = this.updateStatus;
    return {'deleteStatus': ?deleteStatus, 'updateStatus': ?updateStatus};
  }
}

