/// Settings controlling the eviction of unhealthy hosts from the load balancing
/// pool for the backend service.
class OutlierDetection {
  /// The base time that a backend endpoint is ejected for.
  ///
  /// Defaults to 30000ms
  /// or 30s.
  ///
  /// After a backend endpoint is returned back to the load balancing pool, it
  /// can be ejected again in another ejection analysis. Thus, the total
  /// ejection
  /// time is equal to the base ejection time multiplied by the number of times
  /// the backend endpoint has been ejected. Defaults to 30000ms or 30s.
  Duration? baseEjectionTime;

  /// Number of consecutive errors before a backend endpoint is ejected from the
  /// load balancing pool.
  ///
  /// When the backend endpoint is accessed over HTTP, a 5xx
  /// return code qualifies as an error. Defaults to 5.
  core.int? consecutiveErrors;

  /// The number of consecutive gateway failures (502, 503, 504 status or
  /// connection errors that are mapped to one of those status codes) before a
  /// consecutive gateway failure ejection occurs.
  ///
  /// Defaults to 3.
  core.int? consecutiveGatewayFailure;

  /// The percentage chance that a backend endpoint will be ejected when an
  /// outlier status is detected through consecutive 5xx.
  ///
  /// This setting can be
  /// used to disable ejection or to ramp it up slowly. Defaults to 0.
  core.int? enforcingConsecutiveErrors;

  /// The percentage chance that a backend endpoint will be ejected when an
  /// outlier status is detected through consecutive gateway failures.
  ///
  /// This
  /// setting can be used to disable ejection or to ramp it up slowly. Defaults
  /// to 100.
  core.int? enforcingConsecutiveGatewayFailure;

  /// The percentage chance that a backend endpoint will be ejected when an
  /// outlier status is detected through success rate statistics.
  ///
  /// This setting
  /// can be used to disable ejection or to ramp it up slowly. Defaults to 100.
  ///
  /// Not supported when the backend service uses Serverless NEG.
  core.int? enforcingSuccessRate;

  /// Time interval between ejection analysis sweeps.
  ///
  /// This can result in both new
  /// ejections and backend endpoints being returned to service. The interval is
  /// equal to the number of seconds as defined in
  /// outlierDetection.interval.seconds plus the number of nanoseconds as
  /// defined
  /// in outlierDetection.interval.nanos. Defaults to 1 second.
  Duration? interval;

  /// Maximum percentage of backend endpoints in the load balancing pool for the
  /// backend service that can be ejected if the ejection conditions are met.
  /// Defaults to 50%.
  core.int? maxEjectionPercent;

  /// The number of backend endpoints in the load balancing pool that must have
  /// enough request volume to detect success rate outliers.
  ///
  /// If the number of
  /// backend endpoints is fewer than this setting, outlier detection via
  /// success
  /// rate statistics is not performed for any backend endpoint in the load
  /// balancing pool. Defaults to 5.
  ///
  /// Not supported when the backend service uses Serverless NEG.
  core.int? successRateMinimumHosts;

  /// The minimum number of total requests that must be collected in one
  /// interval
  /// (as defined by the interval duration above) to include this backend
  /// endpoint in success rate based outlier detection.
  ///
  /// If the volume is lower
  /// than this setting, outlier detection via success rate statistics is not
  /// performed for that backend endpoint. Defaults to 100.
  ///
  /// Not supported when the backend service uses Serverless NEG.
  core.int? successRateRequestVolume;

  /// This factor is used to determine the ejection threshold for success rate
  /// outlier ejection.
  ///
  /// The ejection threshold is the difference between the mean
  /// success rate, and the product of this factor and the standard deviation of
  /// the mean success rate: mean - (stdev * successRateStdevFactor). This
  /// factor
  /// is divided by a thousand to get a double. That is, if the desired factor
  /// is 1.9, the runtime value should be 1900. Defaults to 1900.
  ///
  /// Not supported when the backend service uses Serverless NEG.
  core.int? successRateStdevFactor;

  OutlierDetection({
    this.baseEjectionTime,
    this.consecutiveErrors,
    this.consecutiveGatewayFailure,
    this.enforcingConsecutiveErrors,
    this.enforcingConsecutiveGatewayFailure,
    this.enforcingSuccessRate,
    this.interval,
    this.maxEjectionPercent,
    this.successRateMinimumHosts,
    this.successRateRequestVolume,
    this.successRateStdevFactor,
  });

  OutlierDetection.fromJson(core.Map json_)
    : this(
        baseEjectionTime: json_.containsKey('baseEjectionTime')
            ? Duration.fromJson(
                json_['baseEjectionTime']
                    as core.Map<core.String, core.dynamic>,
              )
            : null,
        consecutiveErrors: json_['consecutiveErrors'] as core.int?,
        consecutiveGatewayFailure:
            json_['consecutiveGatewayFailure'] as core.int?,
        enforcingConsecutiveErrors:
            json_['enforcingConsecutiveErrors'] as core.int?,
        enforcingConsecutiveGatewayFailure:
            json_['enforcingConsecutiveGatewayFailure'] as core.int?,
        enforcingSuccessRate: json_['enforcingSuccessRate'] as core.int?,
        interval: json_.containsKey('interval')
            ? Duration.fromJson(
                json_['interval'] as core.Map<core.String, core.dynamic>,
              )
            : null,
        maxEjectionPercent: json_['maxEjectionPercent'] as core.int?,
        successRateMinimumHosts: json_['successRateMinimumHosts'] as core.int?,
        successRateRequestVolume:
            json_['successRateRequestVolume'] as core.int?,
        successRateStdevFactor: json_['successRateStdevFactor'] as core.int?,
      );

  core.Map<core.String, core.dynamic> toJson() {
    final baseEjectionTime = this.baseEjectionTime;
    final consecutiveErrors = this.consecutiveErrors;
    final consecutiveGatewayFailure = this.consecutiveGatewayFailure;
    final enforcingConsecutiveErrors = this.enforcingConsecutiveErrors;
    final enforcingConsecutiveGatewayFailure =
        this.enforcingConsecutiveGatewayFailure;
    final enforcingSuccessRate = this.enforcingSuccessRate;
    final interval = this.interval;
